def daily_sales_events(base: str) -> list[tuple[str, int, str]]:
    """C18: 84일 동안 매일 +8만 원, 매주 금요일 -60만 원."""
    b = d(base)
    out = []
    for i in range(84):
        day = b + timedelta(days=i)
        out.append((day.isoformat(), 8 * M, "일 매출"))
        if day.weekday() == 4:
            out.append((day.isoformat(), -60 * M, "주간 매입"))
    return out
